def sum_sequence(sequence):
  sum = 0
  for num in sequence:
    sum += num
  return sum

def remove_duplicates(string): 
    result = "" 
    prev = '' 

    for char in string:
        if char != prev: 
            result += char
            prev = char
    return result

result = remove_duplicates("AAABBCCCD")
